<?php $title='Absensi Saya';$page='attendance';$pdo=Database::connection();$q=$pdo->prepare('SELECT attendance_date,status,note FROM attendance WHERE student_id=? ORDER BY attendance_date DESC LIMIT 100');$q->execute([current_user()['id']]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Absensi Saya</h1><p>Riwayat kehadiran yang dicatat guru.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Status</th><th>Keterangan</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e(format_date($r['attendance_date'])) ?></td><td><span class="badge <?= $r['status']==='Hadir'?'success':'warning' ?>"><?= e($r['status']) ?></span></td><td><?= e($r['note']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$rows): ?><div class="empty-state">Belum ada data absensi.</div><?php endif; ?></section><?php require __DIR__.'/../_dashboard_end.php'; ?>